}, {
  "tStartMs": 505354,
  "dDurationMs": 1202,
  "segs": [ {
    "utf8": "所以我覺得那個時候"
  } ]
}, {
  "tStartMs": 506556,
  "dDurationMs": 1484,
  "segs": [ {
    "utf8": " 不管說你剛剛講"
