}, {
  "tStartMs": 508040,
  "dDurationMs": 1719,
  "segs": [ {
    "utf8": "《媽媽請你也保重》"
  } ]
}, {
  "tStartMs": 509759,
  "dDurationMs": 2502,
  "segs": [ {
    "utf8": "我今天為什麼突然台語不太輪轉"
